	content: "";
	position: absolute;
	inset: 0;
	background: radial-gradient(
		100% 100% at 50% 50%,
		transparent 0%,
		rgba(0, 0, 0, 0.4) 60%,
		rgba(0, 0, 0, 0.75) 100%
	);
	z-index: 0;
