.case-section {
	position: relative;
	background: linear-gradient(
		180deg,
		var(--cs-card-grad-top) 0%,
		var(--cs-card-grad-bot) 100%
	);
	border: 1px solid var(--cs-border);
	border-radius: var(--cs-radius);
	padding: clamp(1rem, 2vw, 1.75rem);
	box-shadow: var(--cs-shadow);
}

.highlight-section {
	border-left: 3px solid var(--cs-accent);
}

.section-number {
	position: absolute;
	top: 16px;
	right: 18px;
	font-family: "Tronica Mono", monospace;
	font-size: 0.75rem;
	color: var(--cs-fg-dimmer);
	opacity: 0.85;
	letter-spacing: 0.08em;
}

.section-title {
	font-family: "PP Mondwest", serif;
	font-size: clamp(1.25rem, 2.6vw, 1.8rem);
	margin-bottom: 0.75rem;
	color: var(--cs-fg);
	text-shadow: 0 0 12px rgba(119, 207, 255, 0.25);
}

.subsection-title {
	font-family: "PP Mondwest", serif;
	font-size: clamp(1rem, 2vw, 1.25rem);
	margin-bottom: 0.5rem;
	color: var(--cs-fg);
}

.section-content {
	font-family: "Tronica Mono", monospace;
	color: var(--cs-fg-dim);
	line-height: 1.7;
	font-size: clamp(0.95rem, 1.3vw, 1rem);
	margin-bottom: 1rem;
}

/* Bullets */
.bullet-list {
	margin: 0.75rem 0 0 0;
	padding-left: 1.25rem;
}
.bullet-list li {
	font-family: "Tronica Mono", monospace;
	color: var(--cs-fg-dim);
	margin-bottom: 0.6rem;
	line-height: 1.65;
}

/* Challenge / info grid */
.challenge-box {
	background: rgba(255, 255, 255, 0.03);
	border: 1px solid var(--cs-border);
	border-radius: 12px;
	padding: 1rem;
	margin-bottom: 1rem;
}

.info-grid {
	display: grid;
	grid-template-columns: repeat(4, minmax(0, 1fr));
	gap: var(--cs-gap);
	margin-top: 1rem;
}
.info-item {
	background: rgba(255, 255, 255, 0.02);
	border: 1px solid var(--cs-border);
	border-radius: 10px;
	padding: 0.9rem;
}
.info-label {
	font-family: "Tronica Mono", monospace;
	font-size: 0.8rem;
	color: var(--cs-fg-dimmer);
	margin-bottom: 0.25rem;
	letter-spacing: 0.06em;
	text-transform: uppercase;
}
.info-value {
	font-family: "PP Mondwest", serif;
	font-size: 1rem;
}

/* Solution blocks */
.solution-item {
	background: rgba(255, 255, 255, 0.02);
	border: 1px solid var(--cs-border);
	border-radius: 12px;
	padding: 1rem;
	margin-bottom: 0.9rem;
}
.solution-icon {
	filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.35));
	margin-right: 0.35rem;
}

