.results-grid {
	display: grid;
	grid-template-columns: repeat(2, minmax(0, 1fr));
	gap: var(--cs-gap);
}
.result-card {
	background: rgba(255, 255, 255, 0.03);
	border: 1px solid var(--cs-border);
	border-radius: 12px;
	padding: 1rem;
	box-shadow: var(--cs-shadow);
