/* ========================================
   SIDEBAR
======================================== */
.case-sidebar {
	position: sticky;
	top: 90px; /* below fixed navbar */
	display: grid;
	gap: var(--cs-gap);
	height: fit-content;
}

.sidebar-card {
	background: linear-gradient(
		180deg,
		var(--cs-card-grad-top) 0%,
		var(--cs-card-grad-bot) 100%
