	border-top: 0;
}

.sidebar-label {
	font-family: "Tronica Mono", monospace;
	font-size: 0.85rem;
	color: var(--cs-fg-dimmer);
}
.sidebar-value {
	font-family: "Tronica Mono", monospace;
	font-size: 0.95rem;
	color: var(--cs-fg);
	text-align: right;
}

/* Tech tags */
.tech-tags {
	display: flex;
	flex-wrap: wrap;
	gap: 0.5rem;
}
.tech-tag {
	font-family: "Tronica Mono", monospace;
	font-size: 0.85rem;
	padding: 0.35rem 0.6rem;
	border: 1px solid var(--cs-border);
	border-radius: 999px;
	color: var(--cs-fg);
	background: rgba(255, 255, 255, 0.03);
}

/* Metrics */
.metric-item {
	display: flex;
	align-items: baseline;
	justify-content: space-between;
	padding: 0.5rem 0;
	border-top: 1px dashed var(--cs-border);
}
.metric-item:first-of-type {
	border-top: 0;
}
.metric-value {
	font-family: "PP Mondwest", serif;
	font-size: 1.2rem;
	text-shadow: 0 0 10px rgba(255, 255, 255, 0.15);
}
.metric-label {
	font-family: "Tronica Mono", monospace;
	color: var(--cs-fg-dimmer);
	font-size: 0.9rem;
}

/* Sidebar links */
.sidebar-link {
	border-top: 1px dashed var(--cs-border);
	display: flex;
	align-items: center;
	justify-content: space-between;
	gap: 0.75rem;
	padding: 0.6rem 0;
	color: var(--cs-fg) !important;
	transition: transform 0.2s ease, text-shadow 0.2s ease;
}
.sidebar-link:first-of-type {
	border-top: 0;
}
.sidebar-link:hover {
	text-shadow: var(--cs-ring);
	transform: translateY(-1px);
}

.case-hero {
	position: relative;
	min-height: 80vh;
	display: flex;
	align-items: center;
	justify-content: center;
	background-image: var(--hero-bg);
	background-position: center;
	background-size: cover;
	background-repeat: no-repeat;
}

html,
body {
	height: 100%;
	margin: 0;
	padding: 0;
}

.footer {
	margin: 0 !important;
	padding: 2rem 1.5rem;
	background: #272727;
}

/* ========================================
   BOTTOM NAV (Prev / All / Next)
======================================== */
.case-navigation {
	margin-top: 2.5rem;
	display: grid;
	grid-template-columns: 1fr auto 1fr;
	gap: var(--cs-gap);
	align-items: center;
}

.nav-link {
	background: linear-gradient(
		180deg,
		var(--cs-card-grad-top) 0%,
		var(--cs-card-grad-bot) 100%
	);
	border: 1px solid var(--cs-border);
	border-radius: 10px;
	padding: 1rem 1.25rem;
	display: grid;
	gap: 0.25rem;
	text-decoration: none !important;
	color: var(--cs-fg) !important;
	box-shadow: var(--cs-shadow);
	transition: transform 0.25s ease, box-shadow 0.25s ease,
		border-color 0.25s ease;
}
.nav-link.center {
	justify-self: center;
	padding: 0.85rem 1.25rem;
}
.nav-link:hover {
	transform: translateY(-2px);
	border-color: var(--cs-border-strong);
	box-shadow: 0 20px 60px rgba(0, 0, 0, 0.7), 0 0 0 1px rgba(255, 255, 255, 0.1);
}
.nav-direction {
	font-family: "Tronica Mono", monospace;
	font-size: 0.85rem;
	color: var(--cs-fg-dimmer);
}
.nav-title {
	font-family: "PP Mondwest", serif;
	font-size: 1rem;
}

/* ========================================
   MEDIA QUERIES
======================================== */
@media (max-width: 1200px) {
	.case-grid {
		grid-template-columns: 1.6fr 1fr;
	}
}

@media (max-width: 1024px) {
	.case-grid {
		grid-template-columns: 1fr;
	}
	.case-sidebar {
		position: static;
	}
	.info-grid {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}
	.results-grid {
		grid-template-columns: 1fr;
	}
}

@media (max-width: 820px) {
	.case-stats {
		grid-template-columns: repeat(2, minmax(0, 1fr));
	}
}

@media (max-width: 560px) {
	.case-wrapper {
		padding-inline: 0.75rem;
	}
	.case-stats {
		gap: 0.75rem;
	}
	.stat-box {
		padding: 0.9rem;
	}
	.section-number {
		top: 12px;
		right: 14px;
	}
	.sidebar-item {
		grid-template-columns: 1fr;
		text-align: left;
	}
	.sidebar-value {
		text-align: left;
	}
	.case-navigation {
		grid-template-columns: 1fr;
	}
	.nav-link.center {
		order: -1;
		justify-self: stretch;
		text-align: center;
	}
}

